  if (!databaseUrl) {
    console.error('Error: DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  // Parse connection details safely to avoid logging credentials/secrets
  let dbInfo = 'database';
  try {
    // Simple regex to extract host and database name from connection string
    // Format: postgres://user:pass@host:port/dbname
    const urlMatch = databaseUrl.match(/@([^/]+)\/(.+)$/);
    if (urlMatch) {
      const host = urlMatch[1];
      const dbName = urlMatch[2];
      dbInfo = `'${dbName}' on host '${host}'`;
